fn completeStdinWrite(f: *FuzzTestRunner, id: u32, n: usize) !void {
    const instance = &f.instances[id];

    instance.broadcast_written += n;
    if (instance.broadcast_written == f.broadcast.items.len) {
        f.broadcast_undelivered -= 1;
        if (f.broadcast_undelivered == 0) {
            try f.broadcastComplete();
        }
    } else {
        f.addStdinWrite(id);
    }
}

fn addStdoutRead(f: *FuzzTestRunner, id: u32, end: usize) !void {
    const step_owner = f.run.step.owner;
    const gpa = step_owner.allocator;
    const instance = &f.instances[id];

    try instance.message.ensureTotalCapacity(gpa, end);
    const start = instance.message.items.len;
    instance.stdout_vec = .{instance.message.allocatedSlice()[start..end]};
    f.batch.addAt(id * 3 + stdout_i, .{ .file_read_streaming = .{
        .file = instance.child.stdout.?,
        .data = &instance.stdout_vec,
    } });
}

fn addStderrRead(f: *FuzzTestRunner, id: u32) !void {
    const step_owner = f.run.step.owner;
    const gpa = step_owner.allocator;
    const instance = &f.instances[id];

    try instance.stderr.ensureUnusedCapacity(gpa, 1);
    instance.stderr_vec = .{instance.stderr.unusedCapacitySlice()};
    f.batch.addAt(id * 3 + stderr_i, .{ .file_read_streaming = .{
        .file = instance.child.stderr.?,
        .data = &instance.stderr_vec,
    } });
}

fn addStdinWrite(f: *FuzzTestRunner, id: u32) void {
    const instance = &f.instances[id];

    assert(f.broadcast.items.len != instance.broadcast_written);
    instance.stdin_vec = .{f.broadcast.items[instance.broadcast_written..]};
    f.batch.addAt(id * 3 + stdin_i, .{ .file_write_streaming = .{
        .file = instance.child.stdin.?,
        .data = &instance.stdin_vec,
    } });
}

fn instanceEos(f: *FuzzTestRunner, id: u32) !void {
    const step_owner = f.run.step.owner;
    const io = step_owner.graph.io;
    const instance = &f.instances[id];

    instance.child.stdin.?.close(io);
    instance.child.stdin = null;
    const term = try instance.child.wait(io);
    if (!termMatches(.{ .exited = 0 }, term)) {
        f.run.step.result_stderr = try f.mergedStderr();
        try f.saveCrash(id, term);
        return f.run.step.fail("test process unexpectedly {f}", .{fmtTerm(term)});
    }
}

fn saveCrash(f: *FuzzTestRunner, id: u32, term: process.Child.Term) !void {
    const step = &f.run.step;
    const b = step.owner;
    const io = b.graph.io;

    if (f.coverage_id == null) return;

    // Search for the input file corresponding to the instance
    const InputHeader = Build.abi.fuzz.MmapInputHeader;
    var in_r_buf: [@sizeOf(InputHeader)]u8 = undefined;
    var in_r: Io.File.Reader = undefined;
    var in_f: Io.File = undefined;
    var in_name_buf: [12]u8 = undefined;
    var in_name: []const u8 = undefined;
    var i: u32 = 0;
    const header: InputHeader = while (true) {
        const name_prefix = "f" ++ Io.Dir.path.sep_str ++ "in";
        in_name = std.fmt.bufPrint(&in_name_buf, name_prefix ++ "{x}", .{i}) catch unreachable;
        in_f = b.cache_root.handle.openFile(io, in_name, .{
            .lock = .exclusive,
            .lock_nonblocking = true,
        }) catch |e| switch (e) {
            error.FileNotFound => return,
            error.WouldBlock => continue, // Can not be from
            // the crashed instance since it is still locked.
            else => return step.fail("failed to open file '{f}{s}': {t}", .{
                b.cache_root, in_name, e,
            }),
        };

        in_r = in_f.readerStreaming(io, &in_r_buf);
        const header = in_r.interface.takeStruct(InputHeader, .little) catch |e| {
            in_f.close(io);
            switch (e) {
                error.ReadFailed => return step.fail("failed to read file '{f}{s}': {t}", .{
                    b.cache_root, in_name, in_r.err.?,
                }),
                error.EndOfStream => continue,
            }
        };

        if (header.pc_digest == f.coverage_id.? and
            header.instance_id == id and
            header.test_i < f.run.fuzz_tests.items.len)
        {
            break header;
        }

        in_f.close(io);
        if (i == std.math.maxInt(u32)) return;
        i += 1;
    };
    defer in_f.close(io);

    // Save it to a seperate file
    const crash_name = "f" ++ Io.Dir.path.sep_str ++ "crash";
    const out = b.cache_root.handle.createFile(io, crash_name, .{
        .lock = .exclusive, // Multiple run steps could have found a crash at the same time
    }) catch |e| return step.fail("failed to create file '{f}{s}': {t}", .{
        b.cache_root, crash_name, e,
    });
    defer out.close(io);

    var out_w_buf: [512]u8 = undefined;
    var out_w = out.writerStreaming(io, &out_w_buf);
    _ = out_w.interface.sendFileAll(&in_r, .limited(header.len)) catch |e| switch (e) {
        error.ReadFailed => return step.fail("failed to read file '{f}{s}': {t}", .{
            b.cache_root, in_name, in_r.err.?,
        }),
        error.WriteFailed => return step.fail("failed to write file '{f}{s}': {t}", .{
            b.cache_root, crash_name, out_w.err.?,
        }),
    };

    return f.run.step.fail("test '{s}' {f}; input saved to '{f}{s}'", .{
        f.run.fuzz_tests.items[header.test_i],
        fmtTerm(term),
        b.cache_root,
                            b.total_ints + bytes_pos..,
                        ) |order_i, data_i| {
                            input.data.order[order_i] = @intCast(data_i);
                        }
                        uid_data.bytes.deinit(gpa);
                        slice.* = .{ .base = bytes_pos, .len = @intCast(bytes.len) };
                        bytes_pos += @intCast(bytes.len);
                        break :len @intCast(bytes.len);
                    },
                });
                const weighted = input.weighted_uid_slice_i[weighted_pos..][0..weighted_len];
                @memset(weighted, @intCast(uid_i));
                weighted_pos += weighted_len;
            }

            assert(ints_pos == b.total_ints);
            assert(bytes_pos == b.total_bytes);
            assert(weighted_pos == b.weighted_len);

            b.uid_slices.clearRetainingCapacity();
            b.total_ints = 0;
            b.total_bytes = 0;
            b.weighted_len = 0;
            b.smithed_len = Builder.init.smithed_len;
            return input;
        }

        pub fn reset(b: *Builder) void {
            const uid_slices = b.uid_slices.entries.slice();
            for (uid_slices.items(.key), uid_slices.items(.value)) |uid, *uid_data| {
                switch (uid.kind) {
                    .int => uid_data.ints.deinit(gpa),
                    .bytes => uid_data.bytes.deinit(gpa),
                }
            }
            b.uid_slices.clearRetainingCapacity();
            b.bytes_table.clearRetainingCapacity();
            b.total_ints = 0;
            b.total_bytes = 0;
            b.weighted_len = 0;
            b.smithed_len = Builder.init.smithed_len;
        }

        /// Asserts the structure is reset
        pub fn deinit(b: *Builder) void {
            assert(b.uid_slices.entries.len == 0);
            b.uid_slices.deinit(gpa);
            b.bytes_table.deinit(gpa);
            b.* = undefined;
        }
    };
};

pub fn init(n_tests: u32, seed: u64, instance_id: u32, limit: ?u64) Fuzzer {
    const pcs = exec.pc_counters.len;
    if (pcs > math.maxInt(u32)) @panic("too many pcs");

    const mmap_input = map: {
        // Find a free input file. `instance_id` should give one that is not in use;
        // however, this may not be the case if there are multiple libfuzzers running.
        var input_i = instance_id;
        const input_f = while (true) {
            var name_buf: [10]u8 = undefined;
            name_buf[0..2].* = "in".*;
            const hex = std.fmt.bufPrint(name_buf[2..], "{x}", .{input_i}) catch unreachable;
            const name = name_buf[0 .. 2 + hex.len];

            if (exec.cache_f.createFile(io, name, .{
                .read = true,
                .truncate = false,
                .lock = .exclusive,
                .lock_nonblocking = true,
            })) |f| {
                break f;
            } else |e| switch (e) {
                // To ensure no input file is unused to avoid the number of input files
                // growing indefinitely across runs, they are linearly searched through.
                //
                // This could be avoided by creating a shared file holding the current number
                // of input files in use; however, using multiple libfuzzers is uncommon and
                // there should not be that many input files to search through anyways.
                error.WouldBlock => input_i += 1,
                else => panic("failed to create file '{s}': {t}", .{ name, e }),
            }
        };
        break :map MemoryMappedInput.init(input_f, instance_id, input_i);
    };

    const tests = gpa.alloc(Test, n_tests) catch @panic("OOM");
    const seen_pcs_len = bitsetUsizes(pcs);
    var seen_pcs_bufs = gpa.alloc(usize, seen_pcs_len * n_tests) catch @panic("OOM");
    var best_quality_bufs = gpa.alloc(Input.Best, pcs * n_tests) catch @panic("OOM");
    var best_input_bufs = gpa.alloc(Input.Best.Map, pcs * n_tests) catch @panic("OOM");
    @memset(seen_pcs_bufs, 0);
    for (0.., tests) |i, *t| {
        const name = abi.runner_test_name(@intCast(i)).toSlice();
        // A hash is used as the dirname instead of the actual test name since the test name
        // may be not allowed by the filesystem or have a special meaning (e.g. absolute /
        // relative paths).
        const dirname = std.fmt.hex(std.hash.Wyhash.hash(0, name));

        const lock_file = file: {
            if (instance_id != 0) break :file undefined;

            exec.cache_f.createDir(io, &dirname, .default_dir) catch |e| switch (e) {
                error.PathAlreadyExists => {},
                else => panic("failed to create directory '{s}': {t}", .{ &dirname, e }),
            };

            var cname: CorpusFileName = .fromTest(dirname);
            const lock_name = cname.syncLockName();
            break :file exec.cache_f.createFile(io, lock_name, .{
                .truncate = false,
                .lock = .exclusive,
                .lock_nonblocking = true,
            }) catch |e| switch (e) {
                error.WouldBlock => panic("corpus of '{s}' is in use by another fuzzer", .{name}),
                else => panic("failed to create file '{s}': {t}", .{ lock_name, e }),
            };
        };

        t.* = .{
            .seen_pcs = seen_pcs_bufs[0..seen_pcs_len],
            .bests = .{
                .len = 0,
                .quality_buf = best_quality_bufs[0..pcs],
                .input_buf = best_input_bufs[0..pcs],
