            .seen_uids = .empty,

            .corpus = .empty,
            .corpus_pos = @enumFromInt(0),
            .start_mut_corpus = math.maxInt(u32),
            .dirname = dirname,
            .lock_file = lock_file,
            .received = .empty,

            .limit = limit,
            .batch_cycles = 1,
            .batches = 0,
            .batches_since_find = 0,

